use ark_bn254::{Fq as Aq,Fr as Ar};use ark_ff::{BigInteger,Field,PrimeField};use num_bigint::{BigInt as Z,Sign};use zopro_bn254::{FpConfig,FqConfig,FrConfig,ifma8::Ifma8};
fn z(n:u64)->Z{Z::from(n)}fn words(w:[u64;4])->Z{Z::from_bytes_le(Sign::Plus,&w.into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>())}fn w(x:&Z)->[u64;4]{let(s,v)=x.to_u64_digits();assert_ne!(s,Sign::Minus);assert!(v.len()<=4);let mut out=[0;4];out[..v.len()].copy_from_slice(&v);out}fn md(x:Z,p:&Z)->Z{let r=x%p;if r<z(0){r+p}else{r}}fn af<A:PrimeField>(x:&Z)->A{let(s,b)=x.to_bytes_le();let a=A::from_le_bytes_mod_order(&b);if s==Sign::Minus{-a}else{a}}fn ai<A:PrimeField>(x:A)->Z{Z::from_bytes_le(Sign::Plus,&x.into_bigint().to_bytes_le())}fn next(s:&mut u64)->u64{*s^=*s<<13;*s^=*s>>7;*s^=*s<<17;*s}fn rnd(s:&mut u64,p:&Z)->Z{words(std::array::from_fn(|_|next(s)))%p}
#[inline(never)]fn call<C:FpConfig,const MODE:usize>(a:&[Ifma8<C,true>;6])->Ifma8<C,true>{match MODE{0=>a[0].affine_mul_minus(&a[1],&a[4]),1=>a[0].affine_mul_minus_sum(&a[1],&a[4],&a[5]),2=>a[0].affine_mul_double_minus_sum(&a[1],&a[4],&a[5]),3=>a[0].affine_sum2_minus(&a[1],&a[2],&a[3],&a[4]),4=>a[0].affine_difference2_minus(&a[1],&a[2],&a[3],&a[4]),_=>panic!("invalid mode")}}
fn check<C:FpConfig,A:PrimeField>()->usize{let p=words(C::P);assert_eq!(p,Z::from_bytes_le(Sign::Plus,&A::MODULUS.to_bytes_le()));let two=&p*z(2);let rinv=A::from(2u64).pow([256]).inverse().unwrap();let mut edge=vec![z(0),z(1),&p-z(1),p.clone(),&p+z(1),&two-z(1),two.clone()];for bit in[1usize,51,52,53,63,64,103,104,105,127,128,155,156,157,191,192,207,208,209,251,252,253]{let x=z(1)<<bit;for d in[-1i64,0,1]{let v=&x+Z::from(d);if v>=z(0)&&v<=two{edge.push(v);}}}edge.sort();edge.dedup();let n=edge.len();assert_eq!(n,72);let rows=n*n+2048+512;let mut rng=0x616666696e652d6f;let mut chain:[[Z;8];6]=std::array::from_fn(|j|std::array::from_fn(|_|rnd(&mut rng,if j<4{&two}else{&p})));let mut count=0;let mut noncanonical=[0u64;5];
 for row in 0..rows{let input:[[Z;8];6]=if row<n*n{std::array::from_fn(|j|std::array::from_fn(|i|{let index=match j{0=>(row/n+i)%n,1=>(row%n+3*i)%n,2=>(row/n+7*(row%n)+5*i+1)%n,3=>(11*(row/n)+row%n+7*i+3)%n,4=>(3*(row/n)+row%n+11*i)%n,_=>(row/n+5*(row%n)+13*i+1)%n};let x=edge[index].clone();if j<4{x}else{x%&p}}))}else if row<n*n+2048{std::array::from_fn(|j|std::array::from_fn(|_|rnd(&mut rng,if j<4{&two}else{&p})))}else{chain.clone()};for j in 0..6{assert!(input[j].iter().all(|v|v>=&z(0)&&(if j<4{v<=&two}else{v<&p})));}
 let a:[Ifma8<C,true>;6]=std::array::from_fn(|j|unsafe{Ifma8::affine_offset_from_raw(&input[j].each_ref().map(|x|w(x)))});let outputs=[call::<C,0>(&a),call::<C,1>(&a),call::<C,2>(&a),call::<C,3>(&a),call::<C,4>(&a)];let prod=a[0].mul(&a[1]);let xs=a[4].add_canonical(&a[5]);let original=[prod.sub(&a[4]),prod.sub(&xs),prod.add(&prod).sub(&xs),a[0].sum2(&a[1],&a[2],&a[3]).sub(&a[4]),a[0].difference2(&a[1],&a[2],&a[3]).sub(&a[4])];
 for(mode,out)in outputs.iter().enumerate(){let digits=out.affine_offset_raw_digits();let exported=out.get();assert_eq!(exported,original[mode].get());for lane in 0..8{assert!(digits.iter().all(|d|d[lane]<(1<<52)));let value:Z=digits.iter().enumerate().map(|(i,d)|Z::from(d[lane])<<(52*i)).sum();assert!(value>=z(0)&&value<two);noncanonical[mode]+=u64::from(value>=p);let[a,b,c,d,x,y]=input.each_ref().map(|v|v[lane].clone());let sum=mode==1||mode==2;let scale=if mode==2{2u64}else{1};let numerator=af::<A>(&a)*af::<A>(&b)+if mode==3{af::<A>(&c)*af::<A>(&d)}else if mode==4{-af::<A>(&c)*af::<A>(&d)}else{A::ZERO};let expected=numerator*rinv*A::from(scale)-af::<A>(&x)-if sum{af::<A>(&y)}else{A::ZERO};assert_eq!(md(value,&p),ai(expected));assert_eq!(words(exported[lane].0),ai(expected));count+=1;}
 }
 if row>=n*n+2048{let selected=row%5;let digits=outputs[selected].affine_offset_raw_digits();let raw:[Z;8]=std::array::from_fn(|i|digits.iter().enumerate().map(|(j,d)|Z::from(d[i])<<(52*j)).sum());chain.rotate_left(1);chain[0]=raw;for j in 4..6{for i in 0..8{chain[j][i]=md(chain[j][i].clone(),&p);}}}
 }
 assert!(noncanonical.iter().all(|&n|n>0));println!("AFFINE_OFFSET_NATIVE prime={} edges={n} rows={rows} raw_outputs={count} Ark_exports={count} original_exports={count} noncanonical={noncanonical:?}",if C::P==FqConfig::P{"Fq"}else{"Fr"});count}
#[test]fn fq_native_all_operations_edges_and_chains(){assert_eq!(check::<FqConfig,Aq>(),309760);}
#[test]fn fr_native_all_operations_edges_and_chains(){assert_eq!(check::<FrConfig,Ar>(),309760);}
